def f(N: int, M: int, pairs: List[Tuple[int, int]]) -> int:
    parent = list(range(N))

    def find(x):
        if parent[x]!= x:
            parent[x] = find(parent[x])
        return parent[x]

    for s, t in pairs:
        ps = find(s)
        pt = find(t)
        if ps!= pt:
            parent[pt] = ps

    return sum(1 for i in range(1, N) if find(0) == find(i))
